-- Voiding an unposted draft records a cancellation without manufacturing ledger entries.
DROP TRIGGER fb_sales_revision_insert;
CREATE TRIGGER fb_sales_revision_insert BEFORE INSERT ON sales_invoicerevision
BEGIN
 SELECT RAISE(ABORT,'invoice_history_immutable: Invoice revisions are immutable') WHERE EXISTS(SELECT 1 FROM sales_invoicerevision WHERE id=NEW.id OR (invoice_id=NEW.invoice_id AND number=NEW.number));
 SELECT RAISE(ABORT,'invoice_revision_scope: Invalid revision ownership') WHERE NOT EXISTS(SELECT 1 FROM sales_invoice i JOIN directory_customer c ON c.id=NEW.customer_id WHERE i.id=NEW.invoice_id AND i.revision=NEW.number AND c.company_id=i.company_id);
 SELECT RAISE(ABORT,'invoice_revision_fields: Invalid invoice revision fields') WHERE json_extract(NEW.data,'$.id') IS NOT NEW.id OR json_extract(NEW.data,'$.number') IS NOT NEW.number OR json_extract(NEW.data,'$.customer_id') IS NOT NEW.customer_id OR json_extract(NEW.data,'$.date') IS NOT NEW.date OR json_extract(NEW.data,'$.due_date') IS NOT NEW.due_date OR json_extract(NEW.data,'$.state') IS NOT NEW.state OR json_extract(NEW.data,'$.journal_id') IS NOT NEW.journal_id OR json_extract(NEW.data,'$.reversal_id') IS NOT NEW.reversal_id OR fb_sales_money(json_quote(json_extract(NEW.data,'$.total'))) IS NOT NEW.total OR length(json_extract(NEW.data,'$.memo'))>2000 OR length(json_extract(NEW.data,'$.reason'))>500;
 SELECT RAISE(ABORT,'invoice_transition: Invalid invoice state transition') WHERE (NEW.number=1 AND (NEW.state<>'DRAFT' OR json_extract(NEW.data,'$.action') IS NOT 'created')) OR (NEW.number>1 AND NOT EXISTS(SELECT 1 FROM sales_invoicerevision r WHERE r.invoice_id=NEW.invoice_id AND r.number=NEW.number-1 AND ((r.state='DRAFT' AND (NEW.state IN('DRAFT','OPEN') OR (NEW.state='VOID' AND json_extract(NEW.data,'$.action')='cancelled'))) OR (r.state='OPEN' AND NEW.state='VOID'))));
 SELECT RAISE(ABORT,'invoice_financial_immutable: Posting and void preserve financial evidence') WHERE NEW.state IN('OPEN','VOID') AND json_remove(NEW.data,'$.id','$.number','$.state','$.action','$.reason','$.actor_name','$.journal_id','$.reversal_id','$.review_digest','$.cancelled_date') IS NOT (SELECT json_remove(data,'$.id','$.number','$.state','$.action','$.reason','$.actor_name','$.journal_id','$.reversal_id','$.review_digest','$.cancelled_date') FROM sales_invoicerevision WHERE invoice_id=NEW.invoice_id AND number=NEW.number-1);
 SELECT RAISE(ABORT,'invoice_posting_link: Invalid invoice posting linkage') WHERE
 (NEW.state='DRAFT' AND (NEW.journal_id IS NOT NULL OR NEW.reversal_id IS NOT NULL OR json_extract(NEW.data,'$.review_digest') IS NOT '')) OR
 ((NEW.state='OPEN' OR (NEW.state='VOID' AND NEW.journal_id IS NOT NULL)) AND (NEW.total<=0 OR NOT EXISTS(SELECT 1 FROM ledger_journal j JOIN sales_invoice i ON i.identity_id=j.source_id WHERE i.id=NEW.invoice_id AND j.id=NEW.journal_id AND j.company_id=i.company_id AND j.date=NEW.date AND j.status='POSTED' AND j.reversal_of_id IS NULL))) OR
 (NEW.state='OPEN' AND (NEW.reversal_id IS NOT NULL OR length(json_extract(NEW.data,'$.review_digest'))<>64)) OR
 (NEW.state='VOID' AND NEW.journal_id IS NOT NULL AND (trim(json_extract(NEW.data,'$.reason'))='' OR NEW.journal_id IS NOT (SELECT journal_id FROM sales_invoicerevision WHERE invoice_id=NEW.invoice_id AND number=NEW.number-1) OR json_extract(NEW.data,'$.review_digest') IS NOT (SELECT json_extract(data,'$.review_digest') FROM sales_invoicerevision WHERE invoice_id=NEW.invoice_id AND number=NEW.number-1) OR NOT EXISTS(SELECT 1 FROM ledger_journal j WHERE j.id=NEW.reversal_id AND j.reversal_of_id=NEW.journal_id AND j.status='POSTED')));
 SELECT RAISE(ABORT,'invoice_cancellation: Only an unposted draft may be cancelled without reversal') WHERE
 (NEW.state='VOID' AND NEW.journal_id IS NULL AND (NEW.reversal_id IS NOT NULL OR json_extract(NEW.data,'$.review_digest') IS NOT '' OR json_extract(NEW.data,'$.action') IS NOT 'cancelled' OR coalesce(trim(json_extract(NEW.data,'$.reason')),'')='' OR json_type(NEW.data,'$.cancelled_date') IS NOT 'text' OR NOT coalesce(fb_valid_date(json_extract(NEW.data,'$.cancelled_date')),0) OR json_extract(NEW.data,'$.cancelled_date')<NEW.date OR NOT EXISTS(SELECT 1 FROM sales_invoicerevision p WHERE p.invoice_id=NEW.invoice_id AND p.number=NEW.number-1 AND p.state='DRAFT')))
 OR (NOT (NEW.state='VOID' AND NEW.journal_id IS NULL) AND json_type(NEW.data,'$.cancelled_date') IS NOT NULL);
 SELECT RAISE(ABORT,'invoice_live_receipts: Reverse live receipts before voiding an invoice') WHERE NEW.state='VOID' AND EXISTS(SELECT 1 FROM sales_receiptallocation a WHERE a.invoice_id=NEW.invoice_id AND NOT EXISTS(SELECT 1 FROM sales_receiptreversal z WHERE z.receipt_id=a.receipt_id));
END;
DROP TRIGGER fb_sales_invoice_seal;
CREATE TRIGGER fb_sales_invoice_seal BEFORE INSERT ON sales_seal WHEN NEW.kind='sales_invoice_revision'
BEGIN
 SELECT RAISE(ABORT,'invoice_complete: Invoice requires real revision') WHERE NOT EXISTS(SELECT 1 FROM sales_invoicerevision WHERE id=NEW.doc_id);
 SELECT RAISE(ABORT,'invoice_complete: Incomplete or inconsistent invoice totals') WHERE EXISTS(SELECT 1 FROM sales_invoicerevision r WHERE r.id=NEW.doc_id AND NOT fb_invoice_document_ok(r.data,coalesce((SELECT json_group_array(json(l.data)) FROM (SELECT data FROM sales_invoiceline WHERE revision_id=r.id ORDER BY position) l),'[]'),r.total));
 SELECT RAISE(ABORT,'invoice_financial_immutable: Posting and void must copy exact lines') WHERE EXISTS(SELECT 1 FROM sales_invoicerevision r JOIN sales_invoicerevision p ON p.invoice_id=r.invoice_id AND p.number=r.number-1 WHERE r.id=NEW.doc_id AND r.state IN('OPEN','VOID') AND (EXISTS(SELECT data FROM sales_invoiceline WHERE revision_id=r.id EXCEPT SELECT data FROM sales_invoiceline WHERE revision_id=p.id) OR EXISTS(SELECT data FROM sales_invoiceline WHERE revision_id=p.id EXCEPT SELECT data FROM sales_invoiceline WHERE revision_id=r.id)));
 SELECT RAISE(ABORT,'invoice_posting_complete: Invoice posting must exactly match its lines and account evidence') WHERE EXISTS(SELECT 1 FROM sales_invoicerevision r JOIN sales_invoice i ON i.id=r.invoice_id WHERE r.id=NEW.doc_id AND r.state IN('OPEN','VOID') AND r.journal_id IS NOT NULL AND (EXISTS(SELECT 1 FROM sales_journal_mismatch WHERE id=r.journal_id) OR EXISTS(SELECT 1 FROM sales_reference_mismatch WHERE id=i.identity_id) OR NOT EXISTS(SELECT 1 FROM documents_documentaccount d JOIN ledger_account a ON a.id=d.account_id WHERE d.source_id=i.identity_id AND d.role='receivables' AND a.kind='ASSET') OR EXISTS(SELECT 1 FROM sales_invoiceline l LEFT JOIN ledger_account a ON a.id=l.income_account_id WHERE l.revision_id=r.id AND coalesce(json_extract(l.data,'$.line_kind'),'CHARGE')<>'NOTE' AND (a.id IS NULL OR a.kind<>'INCOME'))));
END;
DROP TRIGGER fb_sales_invoice_tax_account;
CREATE TRIGGER fb_sales_invoice_tax_account BEFORE INSERT ON sales_seal WHEN NEW.kind='sales_invoice_revision'
BEGIN SELECT RAISE(ABORT,'sales_tax_account: Collected tax requires a liability account in this company') WHERE EXISTS(SELECT 1 FROM sales_invoicerevision r JOIN sales_invoice i ON i.id=r.invoice_id WHERE r.id=NEW.doc_id AND r.state IN('OPEN','VOID') AND r.journal_id IS NOT NULL AND fb_sales_money(json_quote(json_extract(r.data,'$.tax')))>0 AND NOT EXISTS(SELECT 1 FROM documents_documentaccount d JOIN ledger_account a ON a.id=d.account_id WHERE d.source_id=i.identity_id AND d.role='collected_tax' AND a.kind='LIABILITY' AND a.company_id=i.company_id)); END;
